<script setup lang="ts">import type{Resume}from'@career-launch/shared';import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{repository}from'../../services/repository';const router=useRouter();const items=ref<Resume[]>([]);async function load(){items.value=await repository.resumes.list()}async function createResume(){const now=new Date().toISOString();const resume:Resume={id:crypto.randomUUID(),userId:'user-student-001',name:'未命名简历',template:'classic',accentColor:'#315cf5',profile:{name:'',email:'student@example.com',phone:'',city:'',targetRole:''},education:[],internships:[],projects:[],skills:[],honors:[],summary:'',updatedAt:now,version:0};await repository.resumes.save(resume);router.push(`/me/resumes/${resume.id}/edit`)}async function remove(id:string){if(!window.confirm('确认删除这份简历？此操作无法撤销。'))return;await repository.resumes.remove(id);await load()}onMounted(load)</script>
<template><section><header class="page-head"><div><h1>我的简历</h1><p>为不同求职方向准备针对性的简历版本。</p></div><button class="cl-primary-button" @click="createResume">新建简历</button></header><div class="resume-grid"><article v-for="resume in items" :key="resume.id" class="resume-card cl-card"><div class="paper-mini"><span>{{resume.profile.name||'你的姓名'}}</span><i></i><i></i><i></i><b :style="{background:resume.accentColor}"></b></div><h2>{{resume.name}}</h2><p>{{resume.profile.targetRole||'尚未填写求职方向'}} · 更新于 {{new Date(resume.updatedAt).toLocaleDateString('zh-CN')}}</p><footer><RouterLink class="cl-primary-button" :to="`/me/resumes/${resume.id}/edit`">继续编辑</RouterLink><button class="cl-quiet-button" @click="remove(resume.id)">删除</button></footer></article></div></section></template>
<style scoped>.page-head{display:flex;align-items:start;justify-content:space-between;gap:20px}.page-head h1{margin:0;font-size:30px}.page-head p,.resume-card p{color:var(--cl-muted)}.resume-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:20px}.resume-card{padding:18px}.paper-mini{position:relative;height:150px;overflow:hidden;padding:20px;border-radius:8px;background:var(--cl-canvas)}.paper-mini span{font-weight:800}.paper-mini i{display:block;width:78%;height:5px;margin-top:13px;border-radius:3px;background:var(--cl-border)}.paper-mini i:nth-of-type(2){width:56%}.paper-mini b{position:absolute;top:0;left:0;width:5px;height:100%}.resume-card h2{margin:16px 0 3px;font-size:18px}.resume-card p{margin-bottom:15px;font-size:13px}.resume-card footer{display:flex;gap:8px}@media(max-width:560px){.resume-grid{grid-template-columns:1fr}}</style>
